{
  "findings": [
    {
      "check_id": "CKV_AWS_5",
      "title": "Ensure all data stored in the Elasticsearch is securely encrypted at rest",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "HIGH",
      "explanation": "The `encrypt_at_rest` block explicitly sets `enabled = false`, leaving sensitive log data unencrypted on disk, which violates security best practices and compliance requirements."
    },
    {
      "check_id": "CKV_AWS_6",
      "title": "Ensure all Elasticsearch has node-to-node encryption enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "Node-to-node encryption is not configured. Without it, traffic between nodes within the cluster is transmitted in plaintext, exposing data to potential interception even within the VPC."
    },
    {
      "check_id": "CKV_AWS_228",
      "title": "Verify Elasticsearch domain is using an up to date TLS policy",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "No `domain_endpoint_options` are defined, meaning the domain defaults to older TLS policies (e.g., TLS 1.0/1.1) for REST API endpoints, which are considered insecure."
    },
    {
      "check_id": "CKV_AWS_317",
      "title": "Ensure Elasticsearch Domain Audit Logging is enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "Audit logging is not enabled. This prevents tracking of user actions and access patterns, hindering incident response and compliance auditing capabilities."
    },
    {
      "check_id": "CKV_AWS_84",
      "title": "Ensure Elasticsearch Domain Logging is enabled",
      "resource": "aws_elasticsearch_domain.log_search_database",
      "severity": "MEDIUM",
      "explanation": "Standard error and slow logs are not configured. Without these logs, troubleshooting performance issues or detecting malicious activity within the cluster is significantly more difficult."
    }
  ],
  "patched_code": "resource "aws_elasticsearch_domain" "log_search_database" {
  domain_name           = "enterprise-log-analytics-es"
  elasticsearch_version = "7.10"

  cluster_config {
    instance_type  = var.elasticsearch_instance_type
    instance_count = 2
  }

  vpc_options {
    subnet_ids         = [aws_subnet.data_subnet_az1.id]
    security_group_ids = [aws_security_group.elasticsearch_sg.id]
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 20
    volume_type = "gp2"
  }

  encrypt_at_rest {
    enabled = true
  }

  node_to_node_encryption {
    enabled = true
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  log_publishing_options {
    log_type                 = "INDEX_SLOW_LOGS"
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.es_logs.arn
  }

  log_publishing_options {
    log_type                 = "SEARCH_SLOW_LOGS"
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.es_logs.arn
  }

  log_publishing_options {
    log_type                 = "ES_APPLICATION_LOGS"
    cloudwatch_log_group_arn = aws_cloudwatch_log_group.es_logs.arn
  }

  audit_options {
    enabled = true
    log_publishing_options {
      cloudwatch_log_group_arn = aws_cloudwatch_log_group.es_audit_logs.arn
    }
  }
}

resource "aws_cloudwatch_log_group" "es_logs" {
  name              = "/aws/es/${aws_elasticsearch_domain.log_search_database.domain_name}/logs"
  retention_in_days = 30
}

resource "aws_cloudwatch_log_group" "es_audit_logs" {
  name              = "/aws/es/${aws_elasticsearch_domain.log_search_database.domain_name}/audit-logs"
  retention_in_days = 30
}",
  "fix_summary": "Enabled encryption at rest and node-to-node encryption. Configured a modern TLS security policy (TLS 1.2+) and enforced HTTPS. Added CloudWatch Log Groups and configured `log_publishing_options` for standard logs (index/search slow logs, application logs) and `audit_options` for audit logging."
}
